#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Самораспаковывающийся запуск финального отчёта по пробегам и заправкам."""
from __future__ import annotations

import base64
import gzip

_PAYLOAD = """"""

_source = gzip.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8")
exec(compile(_source, __file__, "exec"), {"__name__": "__main__", "__file__": __file__})
